// Phase 3D.3 — ADMIN "Normalize Command". n8n Code node body.
// Extends private/ADMIN-Normalize_Command.before.js with Telegram callback_query support.

const j = $input.first().json;
// Telegram Trigger: update at root. Harness webhook may wrap under .body.
const root = (j && j.body && (j.body.message || j.body.text || j.body.callback_query)) ? j.body : j;

if (root.callback_query) {
  const cq = root.callback_query || {};
  const data = String(cq.data || '');
  const from = cq.from || {};
  const msg = cq.message || {};
  const chat = msg.chat || {};

  let action = 'unknown';
  let action_token = '';
  if (data.startsWith('sm:p:')) { action = 'processed'; action_token = data.slice(5); }
  else if (data.startsWith('sm:s:')) { action = 'spam'; action_token = data.slice(5); }

  return [{ json: {
    command: '/__callback',
    command_raw: '/__callback',
    args: [],
    text: '',
    callback_data: data,
    callback_query_id: String(cq.id || ''),
    callback_message_id: String(msg.message_id || ''),
    callback_chat_id: String(chat.id || ''),
    user_id: String(from.id || ''),
    chat_id: String(chat.id || ''),
    action,
    action_token,
    raw_ok: Boolean(data),
  }}];
}

const msg = root.message || root;
const text = String(msg.text || root.text || j.text || '').trim();
const from = msg.from || root.from || j.from || {};
const chat = msg.chat || root.chat || j.chat || {};

// Only the first token is the command; args never match privileged routes.
const parts = text.split(/\s+/).filter(Boolean);
let rawCmd = (parts[0] || '').trim();
// Strip optional @bot_username suffix (Telegram group form)
rawCmd = rawCmd.split('@')[0];
rawCmd = rawCmd.toLowerCase();

const ALIASES = {
  '/aistatus': '/ai_status',
  '/lasterror': '/last_error',
  '/aion': '/ai_on',
  '/aioff': '/ai_off',
  '/foobarunknown': '/foobar_unknown',
};

const command = ALIASES[rawCmd] || rawCmd;
const args = parts.slice(1);

return [{ json: {
  command,
  command_raw: rawCmd,
  args,
  text,
  user_id: String(from.id || root.user_id || j.user_id || ''),
  username: from.username || '',
  chat_id: String(chat.id || root.chat_id || j.chat_id || ''),
  raw_ok: Boolean(text),
}}];

// Phase 3D.4 — ADMIN "Check User Authorization". SYNC: private/auth-lib.mjs
/**
 * Phase 3D.4 — role-aware Telegram authorization for Admin.dev.
 * Pure module — no secrets / Telegram IDs in fixtures.
 */

const ADMIN_ONLY_COMMANDS = new Set([
  '/config',
  '/health',
  '/status',
  '/stats',
  '/last_error',
  '/ai_on',
  '/ai_off',
  '/ai_status',
  '/leads',
  '/test_lead',
  '/aistatus',
  '/lasterror',
]);

const MANAGER_COMMANDS = new Set(['/start', '/help', '/__callback']);

function parseIds(value) {
  if (Array.isArray(value)) return value.map((v) => String(v).trim()).filter(Boolean);
  return String(value || '').split(/[,;\s]+/).map((v) => v.trim()).filter(Boolean);
}

/**
 * Authorize a Telegram user for a normalized command.
 * When manager_action_user_ids is empty, callback authorization falls back to
 * admin_user_ids (legacy 3D.3 behavior). For role identity on callbacks, an
 * empty manager list does NOT grant manager auth_role to non-admins.
 */
function authorizeUser({ user_id, command, admin_user_ids, manager_action_user_ids }) {
  const uid = String(user_id || '');
  const cmd = String(command || '').trim().toLowerCase();
  const admins = parseIds(admin_user_ids);
  const managersConfigured = parseIds(manager_action_user_ids);
  const isAdmin = admins.length > 0 && admins.includes(uid);
  const isManagerListed = managersConfigured.length > 0 && managersConfigured.includes(uid);

  if (cmd === '/__callback') {
    const callbackAllow = managersConfigured.length > 0 ? managersConfigured : admins;
    const canCallback = isAdmin || (callbackAllow.length > 0 && callbackAllow.includes(uid));
    if (canCallback) {
      return {
        authorized: true,
        auth_role: isAdmin ? 'admin' : (isManagerListed ? 'manager' : 'admin'),
        manager_action_authorized: true,
        deny_reason: null,
      };
    }
    return {
      authorized: false,
      auth_role: 'unauthorized',
      manager_action_authorized: false,
      deny_reason: 'unauthorized',
    };
  }

  if (MANAGER_COMMANDS.has(cmd)) {
    if (isAdmin) {
      return { authorized: true, auth_role: 'admin', manager_action_authorized: true, deny_reason: null };
    }
    if (isManagerListed) {
      return { authorized: true, auth_role: 'manager', manager_action_authorized: true, deny_reason: null };
    }
    return { authorized: false, auth_role: 'unauthorized', manager_action_authorized: false, deny_reason: 'unauthorized' };
  }

  if (ADMIN_ONLY_COMMANDS.has(cmd)) {
    if (isAdmin) {
      return { authorized: true, auth_role: 'admin', manager_action_authorized: true, deny_reason: null };
    }
    if (isManagerListed) {
      return {
        authorized: false,
        auth_role: 'manager',
        manager_action_authorized: true,
        deny_reason: 'admin_only',
      };
    }
    return { authorized: false, auth_role: 'unauthorized', manager_action_authorized: false, deny_reason: 'unauthorized' };
  }

  if (isAdmin) {
    return { authorized: true, auth_role: 'admin', manager_action_authorized: true, deny_reason: null };
  }
  if (isManagerListed) {
    return {
      authorized: false,
      auth_role: 'manager',
      manager_action_authorized: true,
      deny_reason: 'admin_only',
    };
  }
  return { authorized: false, auth_role: 'unauthorized', manager_action_authorized: false, deny_reason: 'unauthorized' };
}

function contourLabel(config = {}) {
  const env = String(config.environment || 'dev').toLowerCase();
  const isProd = env === 'production' || env === 'prod';
  return isProd ? 'рабочий' : 'разработка';
}

function aiLabel(config = {}) {
  const on = config.ai_enabled === true || config.ai_enabled === 'true';
  return on ? 'включён' : 'выключен';
}

function startReply(role, config = {}) {
  if (role === 'admin') {
    return [
      'Sales Manager Admin запущен.',
      '',
      'Контур: ' + contourLabel(config),
      'Режим ИИ: ' + aiLabel(config),
      '',
      'Используйте /help, чтобы посмотреть доступные команды.',
    ].join('\n');
  }
  if (role === 'manager') {
    return [
      'Sales Manager готов к работе.',
      '',
      'Здесь приходят новые заявки клиентов.',
      '',
      'В карточке можно:',
      '• скопировать имя и контакт;',
      '• скопировать готовый ответ;',
      '• отметить лид обработанным;',
      '• отметить лид как спам.',
      '',
      'Используйте /help для краткой инструкции.',
    ].join('\n');
  }
  return [
    'Доступ к боту не настроен.',
    'Обратитесь к администратору.',
  ].join('\n');
}

function helpReply(role) {
  if (role === 'manager') {
    return [
      'Помощь по работе с лидами',
      '',
      '🟢 Новый лид — новая заявка',
      '🟡 Повторный — контакт уже встречался',
      '🟠 Возможный повтор — совпал сайт',
      '🔵 Повторная обработка — техническое повторное прохождение',
      '',
      'Действия:',
      '✅ Обработан — вы связались с клиентом',
      '🚫 Спам — заявка нецелевая или мусорная',
      '',
      'Нажмите на имя, контакт или блок ответа, чтобы скопировать.',
    ].join('\n');
  }
  return [
    '📖 Команды Sales Manager Admin',
    '',
    '🚀 Начало:',
    '/start — открыть панель бота',
    '',
    '📊 Состояние:',
    '/status — состояние процессов',
    '/health — проверка зависимостей',
    '/stats — статистика за 7 дней',
    '/last_error — последняя ошибка',
    '',
    '🕘 История:',
    '/leads 3 — последние 3 карточки лидов из архива',
    '/leads 5 — последние 5 карточек лидов из архива',
    '/leads 10 — последние 10 карточек лидов из архива',
    '',
    '🤖 ИИ:',
    '/ai_status — текущий режим',
    '/ai_on — включить ИИ',
    '/ai_off — выключить ИИ',
    '',
    '⚙️ Настройки:',
    '/config — безопасная сводка',
    '/help — список команд',
  ].join('\n');
}

function denyReply({ auth_role, deny_reason, command }) {
  void command;
  if (deny_reason === 'admin_only' && auth_role === 'manager') {
    return 'Команда доступна только администратору.';
  }
  return 'Доступ к боту не настроен.';
}


const lead = $('Normalize Command').first().json;
const rows = $('Read Authorization Config').all().map((i) => i.json);
const map = {};
for (const r of rows) {
  if (r.key != null) map[String(r.key)] = String(r.value ?? '');
}

const decision = authorizeUser({
  user_id: lead.user_id,
  command: lead.command,
  admin_user_ids: map.admin_user_ids,
  manager_action_user_ids: map.manager_action_user_ids,
});

const thisKey = String(($input.first().json && $input.first().json.key) || '');
const firstKey = rows[0] ? String(rows[0].key) : '';
if (rows.length > 1 && thisKey && firstKey && thisKey !== firstKey) {
  return [];
}

return [{
  json: {
    ...lead,
    config_map: map,
    authorized: decision.authorized,
    auth_role: decision.auth_role,
    manager_action_authorized: decision.manager_action_authorized,
    deny_reason: decision.deny_reason,
    environment: map.environment || 'dev',
    ai_enabled: map.ai_enabled === 'true',
  },
}];

