function formatMoscow(v) {
  const s = String(v || '').trim();
  if (!s) return '—';
  const d = new Date(s);
  if (Number.isNaN(d.getTime())) return '—';
  const parts = new Intl.DateTimeFormat('ru-RU', {
    timeZone: 'Europe/Moscow',
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
    hour12: false,
  }).formatToParts(d);
  const get = (t) => parts.find((p) => p.type === t)?.value || '';
  return `${get('day')}.${get('month')}.${get('year')} ${get('hour')}:${get('minute')} МСК`;
}

function envKey() {
  return String(m.environment || 'dev').toLowerCase();
}
function isProd() {
  const k = envKey();
  return k === 'production' || k === 'prod';
}
function contourRu() {
  if (isProd()) return 'рабочий контур';
  const map = { dev: 'разработка', development: 'разработка', sandbox: 'песочница' };
  return map[envKey()] || 'разработка';
}

const ai = (m.ai_enabled === 'true' || m.ai_enabled === true) ? 'включён' : 'выключен';
const pollTs = formatMoscow(m.last_poll_success_at);
const leadTs = formatMoscow(m.last_lead_success_at || m.last_success_at);
const errorTs = formatMoscow(m.last_error_at);

function errorStatusLine() {
  if (!m.last_error_at) return '—';
  const life = String(m.last_error_lifecycle || '').toLowerCase();
  // Explicit open only — otherwise defer to /last_error lifecycle (avoid stale timestamp as "active")
  if (life === 'open') return errorTs;
  return 'нет активных (метка: ' + errorTs + '; детали: /last_error)';
}

