function classifyLifecycle(row) {
  const explicit = String(row.error_lifecycle || row.lifecycle || row.error_status || row.status || '').toLowerCase();
  if (['resolved', 'closed', 'done', 'fixed'].includes(explicit)) return 'resolved';
  if (['controlled_test', 'synthetic', 'test'].includes(explicit)) return 'controlled_test';
