/**
 * Authorize a Telegram user for a normalized command.
 * When manager_action_user_ids is empty, callback authorization falls back to
 * admin_user_ids (legacy 3D.3 behavior). For role identity on callbacks, an
 * empty manager list does NOT grant manager auth_role to non-admins.
 */
function authorizeUser({ user_id, command, admin_user_ids, manager_action_user_ids }) {
  const uid = String(user_id || '');
  const cmd = String(command || '').trim().toLowerCase();
  const admins = parseIds(admin_user_ids);
  const managersConfigured = parseIds(manager_action_user_ids);
  const isAdmin = admins.length > 0 && admins.includes(uid);
  const isManagerListed = managersConfigured.length > 0 && managersConfigured.includes(uid);

  if (cmd === '/__callback') {
    const callbackAllow = managersConfigured.length > 0 ? managersConfigured : admins;
    const canCallback = isAdmin || (callbackAllow.length > 0 && callbackAllow.includes(uid));
    if (canCallback) {
      return {
        authorized: true,
        auth_role: isAdmin ? 'admin' : (isManagerListed ? 'manager' : 'admin'),
        manager_action_authorized: true,
        deny_reason: null,
      };
    }
    return {
      authorized: false,
      auth_role: 'unauthorized',
      manager_action_authorized: false,
      deny_reason: 'unauthorized',
    };
  }

  if (MANAGER_COMMANDS.has(cmd)) {
    if (isAdmin) {
      return { authorized: true, auth_role: 'admin', manager_action_authorized: true, deny_reason: null };
    }
    if (isManagerListed) {
      return { authorized: true, auth_role: 'manager', manager_action_authorized: true, deny_reason: null };
    }
    return { authorized: false, auth_role: 'unauthorized', manager_action_authorized: false, deny_reason: 'unauthorized' };
  }

  if (ADMIN_ONLY_COMMANDS.has(cmd)) {
    if (isAdmin) {
      return { authorized: true, auth_role: 'admin', manager_action_authorized: true, deny_reason: null };
    }
    if (isManagerListed) {
      return {
        authorized: false,
        auth_role: 'manager',
        manager_action_authorized: true,
        deny_reason: 'admin_only',
      };
    }
    return { authorized: false, auth_role: 'unauthorized', manager_action_authorized: false, deny_reason: 'unauthorized' };
  }

  if (isAdmin) {
    return { authorized: true, auth_role: 'admin', manager_action_authorized: true, deny_reason: null };
  }
  if (isManagerListed) {
    return {
      authorized: false,
      auth_role: 'manager',
      manager_action_authorized: true,
      deny_reason: 'admin_only',
    };
  }
  return { authorized: false, auth_role: 'unauthorized', manager_action_authorized: false, deny_reason: 'unauthorized' };
}

